sys_script_include.script:
var IncentNowAccessUtils = Class.create();
IncentNowAccessUtils.prototype = {
    initialize: function() {},

    // =====================================================
    // PLAN SECTION
    // =====================================================
    applyPlanFilter: function(current) {

        var userId = gs.getUserID();

        // ==========================================
        // FULL ACCESS
        // ==========================================
        if (
            gs.getUser().hasRole('admin') ||
            gs.hasRole('x_ctans_incentnow.admin') ||
            gs.hasRole('x_ctans_incentnow.org_executive')
        ) {
            return;
        }

        var hasBGAccess =
            gs.hasRole('x_ctans_incentnow.business_group_executive') ||
            gs.hasRole('x_ctans_incentnow.business_group_admin');

        var hasManager =
            gs.hasRole('x_ctans_incentnow.manager');

        var hasUser =
            gs.hasRole('x_ctans_incentnow.user');

        var condition = null;

        // ==========================================
        // BUSINESS GROUP ACCESS
        // ==========================================
        if (hasBGAccess) {

            var buList = this.getUserBusinessUnits(userId);

            if (buList && buList.length > 0) {

                condition = current.addQuery('business_unit', 'IN', buList.join(','));
            }
        }

        // ==========================================
        // MANAGER / USER ACCESS
        // Resolve Plan IDs through Plan Assignment
        // ==========================================

        var accessibleUsers = [];

        if (hasManager) {

            accessibleUsers = this.getUserAndReportees(userId);

        } else if (hasUser) {

            accessibleUsers.push(userId);
        }

        if (accessibleUsers && accessibleUsers.length > 0) {

            var planAssignmentGR =
                new GlideRecordSecure('x_ctans_incentnow_plan_users');

            planAssignmentGR.addQuery('x_ctans_incentnow_sales_user.user', 'IN', accessibleUsers.join(','));
            planAssignmentGR.query();

            var planIds = [];

            while (planAssignmentGR.next()) {

                var planId = planAssignmentGR.getValue('x_ctans_incentnow_plan');

                if (planId && planIds.indexOf(planId) === -1) {
                    planIds.push(planId);
                }
            }

            if (planIds.length > 0) {

                if (condition) {

                    condition.addOrCondition('sys_id', 'IN', planIds.join(','));

                } else {

                    condition = current.addQuery('sys_id', 'IN', planIds.join(','));
                }
            }
        }
        // ==========================================
        // NO ACCESS
        // ==========================================
        if (!condition) {
            current.addEncodedQuery('sys_idISEMPTY');
        }
    },

    // =====================================================
    // QUOTA SECTION
    // =====================================================
    applyQuotaFilter: function(current) {

        var userId = gs.getUserID();

        // ==========================================
        // FULL ACCESS
        // ==========================================
        if (
            gs.getUser().hasRole('admin') ||
            gs.hasRole('x_ctans_incentnow.admin') ||
            gs.hasRole('x_ctans_incentnow.org_executive')
        ) {
            return;
        }

        var hasBGAccess =
            gs.hasRole('x_ctans_incentnow.business_group_executive') ||
            gs.hasRole('x_ctans_incentnow.business_group_admin');

        var hasManager =
            gs.hasRole('x_ctans_incentnow.manager');

        var hasUser =
            gs.hasRole('x_ctans_incentnow.user');

        var condition = null;

        // ==========================================
        // BUSINESS GROUP ACCESS
        // ==========================================
        if (hasBGAccess) {

            var buList = this.getUserBusinessUnits(userId);

            if (buList && buList.length > 0) {

                condition = current.addQuery(
                    'business_unit',
                    'IN',
                    buList.join(',')
                );
            }
        }

        // ==========================================
        // MANAGER ACCESS
        // Find quotas assigned to manager/reportees
        // ==========================================
        if (hasManager) {

            var users = this.getUserAndReportees(userId);

            if (users && users.length > 0) {

                var qa = new GlideRecordSecure('x_ctans_incentnow_user_quota_assignment');

                // user on Quota Assignment references User Profile,
                // therefore dot-walk directly to sys_user.
                qa.addQuery('user.user', 'IN', users.join(','));
                qa.query();

                var managerQuotaIds = [];

                while (qa.next()) {

                    var quotaId = qa.getValue('quota');

                    if (
                        quotaId && managerQuotaIds.indexOf(quotaId) === -1
                    ) {
                        managerQuotaIds.push(quotaId);
                    }
                }

                if (managerQuotaIds.length > 0) {

                    if (condition) {

                        condition.addOrCondition('sys_id', 'IN', managerQuotaIds.join(','));

                    } else {

                        condition = current.addQuery('sys_id', 'IN', managerQuotaIds.join(','));
                    }
                }
            }
        }

        // ==========================================
        // NORMAL USER ACCESS
        // Only needed when Manager role is absent
        // ==========================================
        if (hasUser && !hasManager) {

            var userQa = new GlideRecordSecure('x_ctans_incentnow_user_quota_assignment');
            userQa.addQuery('user.user', userId);
            userQa.query();

            var userQuotaIds = [];

            while (userQa.next()) {

                var userQuotaId = userQa.getValue('quota');

                if (
                    userQuotaId && userQuotaIds.indexOf(userQuotaId) === -1
                ) {
                    userQuotaIds.push(userQuotaId);
                }
            }

            if (userQuotaIds.length > 0) {

                if (condition) {

                    condition.addOrCondition('sys_id', 'IN', userQuotaIds.join(','));

                } else {

                    condition = current.addQuery('sys_id', 'IN', userQuotaIds.join(','));
                }
            }
        }

        // ==========================================
        // NO ACCESS
        // ==========================================
        if (!condition) {
            current.addEncodedQuery('sys_idISEMPTY');
        }
    },

    // =====================================================
    // QUOTA ASSIGNMENT/ PARTICIPANT ASSIGNMENT/ METRIC REPORT / STATEMENT SECTION
    // =====================================================

    applyAssignmentFilter: function(current) {

        var userId = gs.getUserID();

        // ==========================================
        // FULL ACCESS
        // ==========================================
        if (
            gs.getUser().hasRole('admin') ||
            gs.hasRole('x_ctans_incentnow.admin') ||
            gs.hasRole('x_ctans_incentnow.org_executive')
        ) {
            return;
        }

        var hasBGAccess =
            gs.hasRole('x_ctans_incentnow.business_group_executive') ||
            gs.hasRole('x_ctans_incentnow.business_group_admin');

        var hasManager =
            gs.hasRole('x_ctans_incentnow.manager');

        var hasUser =
            gs.hasRole('x_ctans_incentnow.user');

        var condition = null;

        // ==========================================
        // BUSINESS GROUP ACCESS
        // ==========================================
        if (hasBGAccess) {

            var buList = this.getUserBusinessUnits(userId);

            if (buList && buList.length > 0) {

                condition = current.addQuery('user.business_unit', 'IN', buList.join(','));
            }
        }

        // ==========================================
        // MANAGER ACCESS
        // ==========================================
        if (hasManager) {

            var users = this.getUserAndReportees(userId);

            if (users && users.length > 0) {

                if (condition) {

                    condition.addOrCondition('user.user', 'IN', users.join(','));

                } else {

                    condition = current.addQuery('user.user', 'IN', users.join(','));
                }
            }
        }

        // ==========================================
        // NORMAL USER ACCESS
        // Only needed when Manager role is absent
        // ==========================================
        if (hasUser && !hasManager) {

            if (condition) {

                condition.addOrCondition('user.user', userId);

            } else {

                condition = current.addQuery('user.user', userId);
            }
        }

        // ==========================================
        // NO MATCHING ACCESS
        // ==========================================
        if (!condition) {
            current.addEncodedQuery('sys_idISEMPTY');
        }
    },

    // =====================================================
    // PLAN USER table (Plan Assignment table)
    // =====================================================

    applyPlanAssignmentFilter: function(current) {

        var userId = gs.getUserID();

        // ==========================================
        // FULL ACCESS
        // ==========================================
        if (
            gs.getUser().hasRole('admin') ||
            gs.hasRole('x_ctans_incentnow.admin') ||
            gs.hasRole('x_ctans_incentnow.org_executive')
        ) {
            return;
        }

        var hasBGAccess =
            gs.hasRole('x_ctans_incentnow.business_group_executive') ||
            gs.hasRole('x_ctans_incentnow.business_group_admin');

        var hasManager =
            gs.hasRole('x_ctans_incentnow.manager');

        var hasUser =
            gs.hasRole('x_ctans_incentnow.user');

        var condition = null;

        // ==========================================
        // BUSINESS GROUP ACCESS
        // ==========================================
        if (hasBGAccess) {

            var buList = this.getUserBusinessUnits(userId);

            if (buList && buList.length > 0) {

                condition = current.addQuery('x_ctans_incentnow_sales_user.business_unit', 'IN', buList.join(','));
            }
        }

        // ==========================================
        // MANAGER ACCESS
        // ==========================================
        if (hasManager) {

            var users = this.getUserAndReportees(userId);

            if (users && users.length > 0) {

                if (condition) {

                    condition.addOrCondition('x_ctans_incentnow_sales_user.user', 'IN', users.join(','));

                } else {

                    condition = current.addQuery('x_ctans_incentnow_sales_user.user', 'IN', users.join(','));
                }
            }
        }

        // ==========================================
        // NORMAL USER ACCESS
        // Only needed when Manager role is absent
        // ==========================================
        if (hasUser && !hasManager) {

            if (condition) {

                condition.addOrCondition('x_ctans_incentnow_sales_user.user', userId);

            } else {

                condition = current.addQuery('x_ctans_incentnow_sales_user.user', userId);
            }
        }

        // ==========================================
        // NO MATCHING ACCESS
        // ==========================================
        if (!condition) {
            current.addEncodedQuery('sys_idISEMPTY');
        }
    },

    // =====================================================
    // Earning CREDIT/LOOKUP /PAYOUT  RESULTS SECTION
    // =====================================================

    applyBusinessGroupAdminResultsFilter: function(current) {

        // Skip admins
        if (
            gs.getUser().hasRole('admin') ||
            gs.hasRole('x_ctans_incentnow.admin')
        ) {
            return;
        }

        // Only Business Group Admin
        if (!gs.hasRole('x_ctans_incentnow.business_group_admin')) {
            return;
        }

        var buList = this.getUserBusinessUnits(gs.getUserID());

        // No BU found
        if (buList.length === 0) {
            current.addEncodedQuery('sys_idISEMPTY');
            return;
        }

        // Filter through Plan Business Unit
        current.addQuery(
            'user.business_unit',
            'IN',
            buList.join(',')
        );
    },
    // =====================================================
    // BUSINESS UNIT HELPERS
    // =====================================================

    getUserBusinessUnits: function(userId) {

        var buList = [];

        var profileGR = new GlideRecordSecure('x_ctans_incentnow_user_profile');
        profileGR.addQuery('user', userId);
        profileGR.query();

        while (profileGR.next()) {
            var buId = profileGR.getValue('business_unit');
            if (buId && buList.indexOf(buId) === -1) {
                buList.push(buId);
                this._getChildBUs(buId, buList);
            }
        }

        return buList;
    },

    _getChildBUs: function(parentId, list) {

        var buGR = new GlideRecordSecure('business_unit');
        buGR.addQuery('parent', parentId);
        buGR.query();

        while (buGR.next()) {
            var id = buGR.getUniqueValue();
            if (list.indexOf(id) === -1) {
                list.push(id);
                this._getChildBUs(id, list);
            }
        }
    },

    getUserAndReportees: function(userId) {

        var users = [userId];

        var userGR = new GlideRecordSecure('sys_user');
        userGR.addQuery('manager', userId);
        userGR.query();

        while (userGR.next()) {

            gs.info('REPORTEE=' + userGR.getDisplayValue());

            var reporteeId = userGR.getUniqueValue();

            if (users.indexOf(reporteeId) === -1) {
                users.push(reporteeId);
            }
        }

        gs.info('FINAL USERS=' + users.join(','));

        return users;
    },

    _applyEmptyCheck: function(current, list) {
        if (list.length === 0) {
            return true;
        }
        return false;
    },

    getUserBusinessUnitQuery: function() {

        if (gs.getUser().hasRole('x_ctans_incentnow.admin') || gs.getUser().hasRole('admin')) {
            return [];
        }


        var profile = new GlideRecordSecure('x_ctans_incentnow_user_profile');
        profile.addQuery('user', gs.getUserID());
        profile.query();

        if (!profile.next())
            return [];

        var result = [];

        function collectChildren(buSysId) {

            result.push(buSysId);

            var childBU = new GlideRecordSecure('business_unit');
            childBU.addQuery('parent', buSysId);
            childBU.query();

            while (childBU.next()) {
                collectChildren(childBU.getUniqueValue());
            }
        }

        collectChildren(profile.business_unit.toString());
        //gs.addErrorMessage(JSON.stringify(result));
        return "sys_idIN" + result.join(",");
    },

    type: 'IncentNowAccessUtils'
};
